import{z as n,x as l,o as B,c as d,q as s,j as A,D as e,d as a,s as i,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"文件系统的实现","description":"","frontmatter":{"title":"文件系统的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-fs-implementation.md","filePath":"cs/osk-fs-implementation.md","lastUpdated":1791413859000}'),m={name:"cs/osk-fs-implementation.md"};function c(p,E,f,h,D,F){const r=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=s('<h1 id="文件系统的实现" tabindex="-1">文件系统的实现 <a class="header-anchor" href="#文件系统的实现" aria-label="Permalink to &quot;文件系统的实现&quot;">​</a></h1><div class="epigraph"><p>VFS 的全部承诺是几个内存对象加几张操作表；磁盘愿意怎么排，是每个文件系统自己的事。</p><footer>—— 据 Arpaci-Dusseau, OSTEP；Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/osk-vm-implementation">上一课</a>把文件页接进了页缓存；本课把竖着的路走完：read 与 write 从 VFS 对象一路下到块设备。主干已给平面图：<a href="/cs/vfs">虚拟文件系统</a>、<a href="/cs/dcache">dentry 缓存</a>与<a href="/cs/inode-dir">inode 与目录</a>定了内存对象，<a href="/cs/ext2-block-groups">ext2 块组与位图</a>与<a href="/cs/fat-filesystem">FAT 与目录项</a>给了两种盘上布局。缺口是装配：mount 怎么把盘上布局抬成内存对象，write 又怎么从页缓存一路变成块层请求。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个 write，底下可能是 ext4 的日志、FAT 的簇链，或 tmpfs 的纯内存。实现要回答：分发发生在哪个对象上；页缓存里的脏数据何时、以什么顺序落盘；崩溃之后靠什么不烂。不这么做会错在哪：让每个文件系统自带缓存与脏页管理，就得不到统一的回写节奏、限额与统计；反过来让 write 直写磁盘，缓冲的合并、复用与读改写摊销全部消失——这是当年 Unix 把缓冲缓存做成独立一层的全部理由。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>mount 时读超级块，建根 inode 与根 dentry，从此路径解析只走内存：dcache 命中时名字到 inode 一步不碰盘。每个 VFS 对象各带一张操作表：inode 表管元数据（create、mkdir、unlink），file 表管读写定位，地址空间对象管页缓存。write 的落点是页缓存：把用户数据拷进对应的页并标脏，随即返回——用户此刻就看到成功。回写线程在后台扫描脏页，组成 <a href="/cs/bio-block">bio</a> 交给块层；文件系统在回写之前插入自己的日志提交（<a href="/cs/ext4-journal">日志模式</a>），这就是崩溃一致性的接缝。读路径同样过页缓存：命中则纯内存，未命中才触发一次盘读并把页挂进缓存。</p><p><span class="marginnote">术语翻译：write 返回「成功」只代表数据进了内存的页缓存并被标脏——「脏」就是「这份内存拷贝比盘上的新」；真正的落盘由后台回写线程稍后批量做。所以掉电丢的是「已标脏、还没回写」的那一段：函数返回了不等于已经写进盘。</span></p>',8)),(B(),A(o,null,{default:e(()=>[i(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22write()%22%5D%20--%3E%20VFS%5B%22VFS%20%E5%88%86%E5%8F%91%E5%88%B0%20file%20%E6%93%8D%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20VFS%20--%3E%20PC%5B%22%E6%8B%B7%E5%85%A5%E9%A1%B5%E7%BC%93%E5%AD%98%E5%B9%B6%E6%A0%87%E8%84%8F%22%5D%0A%20%20PC%20--%3E%20RET%5B%22%E5%85%88%E8%BF%94%E5%9B%9E%EF%BC%9A%E7%94%A8%E6%88%B7%E5%B7%B2%E8%A7%81%E6%88%90%E5%8A%9F%22%5D%0A%20%20PC%20--%3E%20WB%5B%22%E5%9B%9E%E5%86%99%E7%BA%BF%E7%A8%8B%E6%89%AB%E6%8F%8F%E8%84%8F%E9%A1%B5%22%5D%0A%20%20WB%20--%3E%20JRN%5B%22%E6%97%A5%E5%BF%97%E6%8F%90%E4%BA%A4%EF%BC%9A%E5%85%88%E6%95%B0%E6%8D%AE%E5%90%8E%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20JRN%20--%3E%20BIO%5B%22%E7%BB%84%E6%88%90%20bio%20%E4%BA%A4%E7%BB%99%E5%9D%97%E5%B1%82%22%5D%0A%20%20BIO%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E5%86%99%E5%85%A5%E8%AE%BE%E5%A4%87%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("装配的关键是两层一致性分开守：页缓存对上层保证「读必见写」——同一张页既是读的来源又是写的去处，自然一致；日志对下层保证「崩溃后元数据自洽」。以最常见的 ordered 模式为例：先刷数据、再提交元数据日志，崩溃后最多丢最后一笔，绝不会出现目录项指向从未写过的块——那种「新文件内容是旧垃圾」的烂态正是没有这层排序时的必然产物。FAT 没有日志、盘上也没有 inode 表，一致性全靠回写顺序的运气，掉电烂目录是"),t("a",{href:"/cs/fat-filesystem"},"结构结果"),a("，不是参数没调好。dcache 的代价与收益也在同一处对账：命中省掉的是每级目录一次盘读，失效则要逐级回盘验证——这就是挂载后第一次列目录慢、第二次快的机制。")],-1)),(B(),A(o,null,{default:e(()=>[i(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%86%99%E5%85%A5%E9%80%94%E4%B8%AD%E7%AA%81%E7%84%B6%E6%8E%89%E7%94%B5%22%5D%20--%3E%20WHEN%7B%22%E5%B4%A9%E6%BA%83%E5%8F%91%E7%94%9F%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%3F%22%7D%0A%20%20WHEN%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E8%BF%98%E6%B2%A1%E5%88%B7%E5%AE%8C%22%7C%20S1%5B%22%E6%97%A5%E5%BF%97%E6%9C%AA%E6%8F%90%E4%BA%A4%3A%20%E7%9B%AE%E5%BD%95%E9%87%8C%E6%B2%A1%E6%9C%89%E6%AD%A4%E6%96%87%E4%BB%B6%22%5D%0A%20%20WHEN%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E5%B7%B2%E5%88%B7%2C%20%E6%97%A5%E5%BF%97%E6%9C%AA%E6%8F%90%E4%BA%A4%22%7C%20S2%5B%22%E6%96%87%E4%BB%B6%E4%B8%8D%E5%87%BA%E7%8E%B0%2C%20%E5%B7%B2%E5%86%99%E5%9D%97%E6%88%90%E5%AD%A4%E5%84%BF%22%5D%0A%20%20WHEN%20--%3E%7C%22%E6%97%A5%E5%BF%97%E5%B7%B2%E6%8F%90%E4%BA%A4%22%7C%20S3%5B%22%E9%87%8D%E6%94%BE%E6%97%A5%E5%BF%97%3A%20%E7%9B%AE%E5%BD%95%E9%A1%B9%E4%B8%8E%E5%9D%97%E5%8F%B7%E8%87%AA%E6%B4%BD%22%5D%0A%20%20S1%20--%3E%20OK%5B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E4%B8%80%E8%87%B4%2C%20%E6%9C%80%E5%A4%9A%E4%B8%A2%E6%9C%80%E5%90%8E%E4%B8%80%E7%AC%94%22%5D%0A%20%20S2%20--%3E%20OK%0A%20%20S3%20--%3E%20OK%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">数字实例：解析 /home/u/a/b/c.txt 要走 5 级目录。dcache 全命中是 5 次内存哈希查找，微秒级；全不命中是 5 次盘读，机械盘一次约 10 毫秒——相差四个数量级。这就是「第一次 ls 慢、第二次快」的全部账目。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>盘上布局细节是 ext2、ext4 与 FAT 各课的对象，本课只取它们与 VFS 的接缝；页缓存替换与脏页策略是<a href="/cs/buffer-dirty">缓冲与脏页</a>的对象，并发与一致性是 <a href="/cs/fs-mmap-coherence">mmap 与页缓存一致</a>的对象，都只引用。分布式与网络文件系统不在此处；挂载命名空间、overlay 这类「目录树本身的管理」也另有专课——本课钉的是单棵树内一次读写的纵向装配。</p><p><span class="marginnote">一条路径解析在 dcache 全命中时是纯内存查找；全不命中则每一级都要读盘验证。同一个网络文件系统上，这个差距从微秒放大到毫秒——目录深度本身就是性能参数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VFS 用内存对象加操作表，把「盘上怎么排」与「内核怎么用」解耦。</li><li>write 落页缓存即返回；回写与日志在后台与崩溃点之间把关。</li><li>两层一致性：页缓存守读必见写，日志守崩溃自洽；FAT 缺第二层是结构必然。</li><li>dcache 把名字解析从每级一次盘读变成纯内存查找，深路径的收益按级数放大。</li><li>出处：Arpaci-Dusseau, <em>OSTEP</em>；Tanenbaum and Bos, <em>Modern Operating Systems</em>。</li></ul>',6))])}const S=n(m,[["render",c]]);export{C as __pageData,S as default};
